			new UNPACK_INFO(AtlasResources.IMAGE_QUICKPLAY_ZOMBOSS, 565, 415, 350, 256, 1, 1, AnimType.AnimType_None, 0, 0, 0, 0.8f)
		};
		mArrays["Quickplay"] = array;
		for (int i = 0; i < array.Length; i++)
		{
			if (Resources.IMAGE_QUICKPLAY == null)
			{
				array[i].mpImage = null;
				continue;
			}
			array[i].mpImage = new Image(Resources.IMAGE_QUICKPLAY, array[i].mX, array[i].mY, array[i].mWidth, array[i].mHeight);
			array[i].mpImage.mNumRows = array[i].mRows;
			array[i].mpImage.mNumCols = array[i].mCols;
			array[i].mpImage.mInvScale = array[i].mInvScale ?? 1f;
		}
		int num = 0;
		AtlasResources.IMAGE_QUICKPLAY_BACKGROUND1_THUMB = array[num].mpImage;
		num++;
